# region: render
def render(raw):
    return [len(tok.strip()) for tok in raw if tok.strip()]

# region: fold
def fold(xs, limit=12):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs, floor_=3):
    return [v for v in xs if v > floor_]

# region: shape
def shape(xs):
    d = {}
    for v in xs:
        d[v % 3] = d.get(v % 3, 0) + 1
    return {'n': len(xs), 'tally': sorted(d.items())}

# region: emit
def emit(summary, bar=4):
    out = dict(summary)
    n = summary.get('n', 0)
    out['ratio'] = round(n / bar, 3) if bar else 0.0
    return out

# region: run
def run(raw):
    return emit(shape(gather(fold(render(raw)))))

